15	const PROCESSING_FEE = 5;
16	const FIRST_INSURANCE_SURCHARGE = 0.1;
17	
18	const BASE_PREMIUMS: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	  potion: 40,
23	  rune: 25,
24	  moonstone: 25,
25	};
26	
27	const COMPONENT_BLOCK_SIZE = 3;
28	const COMPONENT_BLOCK_PREMIUM = 60;
29	
30	type AlikeItems = [type: string, count: number];
31	
32	const groupByType = (items: Item[]): AlikeItems[] => {
33	  const counts = new Map<string, number>();
34	
35	  for (const item of items) {
36	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
37	  }
38	
39	  return [...counts];
40	};
41	
42	const basePremiumOfGroup = ([type, count]: AlikeItems): number => {
43	  if (count === COMPONENT_BLOCK_SIZE) return COMPONENT_BLOCK_PREMIUM;
44	
45	  return count * BASE_PREMIUMS[type];
46	};
47	
48	const basePremiumOf = (items: Item[]): number =>
49	  groupByType(items)
50	    .map(basePremiumOfGroup)
51	    .reduce((total, groupPremium) => total + groupPremium, 0);
52	
53	const quotePremium = (items: Item[]): number => {
54	  const base = basePremiumOf(items);
55	  const withFirstInsuranceSurcharge = base + base * FIRST_INSURANCE_SURCHARGE;
56	
57	  return Math.ceil(withFirstInsuranceSurcharge + PROCESSING_FEE);
58	};
59	
60	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
61	  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
62	});
