const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
  const countByType = new Map<string, number>();

  for (const item of items) {
    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
  }

  return [...countByType];
};

